from __future__ import annotations

from pathlib import Path

PANEL = Path("custom_components/kems/kems16x16.yaml")
TESTS = Path("tests/test_managed_panel.py")

text = PANEL.read_text(encoding="utf-8")

old_boot = '''esphome:\n  name: ${device_name}\n  friendly_name: ${friendly_name}\n  on_boot:\n    priority: -100\n    then:\n      - light.turn_on:\n          id: matrix_light\n          brightness: 35%\n'''
new_boot = '''esphome:\n  name: ${device_name}\n  friendly_name: ${friendly_name}\n  on_boot:\n    priority: -100\n    then:\n      - lambda: |-\n          id(panel_boot_started_ms) = millis();\n          id(panel_boot_ha_seen) = false;\n          id(panel_boot_ha_ready_ms) = 0;\n      - light.turn_on:\n          id: matrix_light\n          brightness: 35%\n'''
if old_boot not in text:
    raise SystemExit("expected on_boot block not found")
text = text.replace(old_boot, new_boot, 1)

globals_block = '''globals:\n  - id: panel_boot_started_ms\n    type: uint32_t\n    restore_value: no\n    initial_value: '0'\n  - id: panel_boot_ha_seen\n    type: bool\n    restore_value: no\n    initial_value: 'false'\n  - id: panel_boot_ha_ready_ms\n    type: uint32_t\n    restore_value: no\n    initial_value: '0'\n\n'''
if "panel_boot_started_ms" not in text.split("select:", 1)[0]:
    text = text.replace("select:\n", globals_block + "select:\n", 1)

old_point = '''      auto bool_colour = [&](bool value) -> Color {\n        return value ? GREEN : RED;\n      };\n      std::string display_mode =\n'''
startup = '''      auto bool_colour = [&](bool value) -> Color {\n        return value ? GREEN : RED;\n      };\n\n      // KEMS boot / OTA completion sequence.\n      const uint32_t boot_elapsed = now - id(panel_boot_started_ms);\n      const bool ha_ready =\n        id(ha_kems_status).has_state() &&\n        !id(ha_kems_status).state.empty() &&\n        id(ha_kems_status).state != "unknown" &&\n        id(ha_kems_status).state != "unavailable";\n\n      auto draw_boot_frame = [&](uint32_t elapsed_ms) {\n        const float intro_pulse =\n          0.30f + 0.70f *\n          (0.5f + 0.5f *\n          sinf((float) elapsed_ms * 2.0f * 3.14159265f / 700.0f));\n        rect(7, 7, 10, 10, scale_color(WHITE, intro_pulse));\n        if (elapsed_ms >= 700) {\n          rect(1, 7, 2, 10, BLUE);\n          flow_horizontal(3, 8, 6, 9, BLUE, BLUE, +1);\n        }\n        if (elapsed_ms >= 1400) {\n          rect(7, 1, 10, 2, YELLOW);\n          flow_vertical(8, 3, 9, 6, YELLOW, YELLOW, +1);\n        }\n        if (elapsed_ms >= 2100) {\n          rect(15, 7, 16, 10, GREEN);\n          flow_horizontal(11, 8, 14, 9, GREEN, GREEN, -1);\n        }\n        if (elapsed_ms >= 2800) {\n          rect(7, 15, 10, 16, MAGENTA);\n          flow_vertical(8, 11, 9, 14, MAGENTA, MAGENTA, +1);\n        }\n        if (elapsed_ms >= 3300) {\n          rect(2, 2, 5, 3, GREEN);\n          rect(12, 2, 15, 3, GREEN);\n          rect(2, 12, 5, 13, GREEN);\n          rect(12, 12, 15, 13, GREEN);\n        }\n      };\n\n      auto draw_waiting_frame = [&]() {\n        const float amount =\n          0.15f + 0.85f *\n          (0.5f + 0.5f *\n          sinf((float) now * 2.0f * 3.14159265f / 1400.0f));\n        const Color WAIT = scale_color(ORANGE, amount);\n        rect(7, 7, 10, 10, WAIT);\n        rect(2, 2, 5, 3, scale_color(YELLOW, 0.35f));\n        rect(12, 2, 15, 3, scale_color(YELLOW, 0.35f));\n        rect(2, 12, 5, 13, scale_color(YELLOW, 0.35f));\n        rect(12, 12, 15, 13, scale_color(YELLOW, 0.35f));\n        flow_horizontal(3, 8, 6, 9, ORANGE, ORANGE, +1);\n        flow_vertical(8, 3, 9, 6, ORANGE, ORANGE, +1);\n        flow_horizontal(11, 8, 14, 9, ORANGE, ORANGE, -1);\n        flow_vertical(8, 11, 9, 14, ORANGE, ORANGE, +1);\n      };\n\n      auto draw_success_frame = [&](uint32_t elapsed_ms) {\n        const float amount =\n          0.20f + 0.80f *\n          (0.5f + 0.5f *\n          sinf((float) elapsed_ms * 2.0f * 3.14159265f / 450.0f));\n        const Color OK = scale_color(GREEN, amount);\n        rect(2, 2, 5, 3, OK);\n        rect(12, 2, 15, 3, OK);\n        rect(2, 12, 5, 13, OK);\n        rect(12, 12, 15, 13, OK);\n        rect(7, 7, 10, 10, OK);\n        rect(7, 1, 10, 2, OK);\n        rect(1, 7, 2, 10, OK);\n        rect(15, 7, 16, 10, OK);\n        rect(7, 15, 10, 16, OK);\n      };\n\n      auto draw_error_frame = [&]() {\n        const float amount =\n          0.10f + 0.90f *\n          (0.5f + 0.5f *\n          sinf((float) now * 2.0f * 3.14159265f / 650.0f));\n        const Color WARN = scale_color(RED, amount);\n        rect(2, 2, 5, 3, WARN);\n        rect(12, 2, 15, 3, WARN);\n        rect(2, 12, 5, 13, WARN);\n        rect(12, 12, 15, 13, WARN);\n        rect(7, 7, 10, 10, WARN);\n      };\n\n      if (boot_elapsed < 3800) {\n        it.fill(OFF);\n        draw_boot_frame(boot_elapsed);\n        return;\n      }\n      if (ha_ready && !id(panel_boot_ha_seen)) {\n        id(panel_boot_ha_seen) = true;\n        id(panel_boot_ha_ready_ms) = now;\n      }\n      if (!id(panel_boot_ha_seen)) {\n        it.fill(OFF);\n        if (boot_elapsed < 20000) {\n          draw_waiting_frame();\n        } else {\n          draw_error_frame();\n        }\n        return;\n      }\n      if ((now - id(panel_boot_ha_ready_ms)) < 1500) {\n        it.fill(OFF);\n        draw_success_frame(now - id(panel_boot_ha_ready_ms));\n        return;\n      }\n\n      std::string display_mode =\n'''
if old_point not in text:
    raise SystemExit("expected display insertion point not found")
text = text.replace(old_point, startup, 1)
PANEL.write_text(text, encoding="utf-8")

tests = TESTS.read_text(encoding="utf-8")
addition = '''\n\ndef test_managed_panel_has_startup_and_ota_completion_animation() -> None:\n    """A managed panel should visibly show boot, waiting, success and fault states."""\n    content = PACKAGED.read_text(encoding="utf-8")\n    assert "panel_boot_started_ms" in content\n    assert "panel_boot_ha_seen" in content\n    assert "draw_boot_frame" in content\n    assert "draw_waiting_frame" in content\n    assert "draw_success_frame" in content\n    assert "draw_error_frame" in content\n    assert "boot_elapsed < 3800" in content\n    assert "boot_elapsed < 20000" in content\n    assert "ha_kems_status).has_state()" in content\n'''
if "test_managed_panel_has_startup_and_ota_completion_animation" not in tests:
    TESTS.write_text(tests.rstrip() + addition + "\n", encoding="utf-8")
